#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <XPT2046_Touchscreen.h>
#include <Adafruit_GFX_Library.h>

// CYD display pins
#define TFT_CS   15
#define TFT_DC   2
#define TFT_RST  -1

// CYD touch pins
#define TOUCH_CS  33
#define TOUCH_IRQ 36

// Display and touch SPI
SPIClass touchSPI(HSPI);

Adafruit_ILI9341 tft(&SPI, TFT_DC, TFT_CS, TFT_RST);
XPT2046_Touchscreen touch(TOUCH_CS, TOUCH_IRQ);

// Screen dimensions (landscape)
#define SW 320
#define SH 240

bool startOpen = false;
int currentApp = 0;

uint16_t blue = 0x3A7B;
uint16_t dark = 0x1824;
uint16_t white = ILI9341_WHITE;

void desktop() {
  currentApp = 0;
  startOpen = false;

  tft.fillScreen(blue);

  // Desktop title
  tft.setTextColor(white);
  tft.setTextSize(2);
  tft.setCursor(12, 10);
  tft.print("Cyd OS");

  // Desktop icons
  tft.fillRoundRect(18, 48, 42, 42, 7, ILI9341_WHITE);
  tft.setTextColor(ILI9341_BLACK);
  tft.setTextSize(1);
  tft.setCursor(18, 94);
  tft.print("Computer");

  tft.fillRoundRect(92, 48, 42, 42, 7, ILI9341_GREEN);
  tft.setCursor(95, 94);
  tft.print("Calculator");

  tft.fillRoundRect(166, 48, 42, 42, 7, ILI9341_YELLOW);
  tft.setCursor(170, 94);
  tft.print("Settings");

  // Taskbar
  tft.fillRect(0, 214, SW, 26, dark);

  tft.fillRoundRect(5, 217, 65, 20, 4, blue);
  tft.setTextColor(white);
  tft.setTextSize(1);
  tft.setCursor(13, 224);
  tft.print("START");

  tft.setCursor(244, 224);
  tft.print("CYD OS");
}

void startMenu() {
  startOpen = true;

  tft.fillRoundRect(5, 85, 155, 125, 6, dark);

  tft.setTextColor(white);
  tft.setTextSize(2);
  tft.setCursor(17, 96);
  tft.print("Cyd OS");

  tft.setTextSize(1);
  tft.setCursor(17, 130);
  tft.print("Calculator");

  tft.setCursor(17, 153);
  tft.print("Settings");

  tft.setCursor(17, 176);
  tft.print("Desktop");
}

void calculator() {
  currentApp = 1;
  startOpen = false;

  tft.fillScreen(ILI9341_BLACK);

  tft.fillRect(0, 0, SW, 32, dark);
  tft.setTextColor(white);
  tft.setTextSize(2);
  tft.setCursor(10, 8);
  tft.print("Calculator");

  tft.fillRect(10, 45, 300, 40, white);
  tft.setTextColor(ILI9341_BLACK);
  tft.setTextSize(2);
  tft.setCursor(20, 58);
  tft.print("0");

  const char* keys[] = {
    "1", "2", "3", "+",
    "4", "5", "6", "-",
    "7", "8", "9", "*",
    "C", "0", "=", "/"
  };

  int x = 10;
  int y = 100;

  for (int i = 0; i < 16; i++) {
    tft.fillRoundRect(x, y, 70, 27, 4, blue);
    tft.setTextColor(white);
    tft.setTextSize(2);
    tft.setCursor(x + 28, y + 7);
    tft.print(keys[i]);

    x += 77;

    if (x > 240) {
      x = 10;
      y += 32;
    }
  }

  tft.fillRect(0, 218, SW, 22, dark);
  tft.setTextSize(1);
  tft.setCursor(10, 225);
  tft.print("Tap START to return");
}

void settings() {
  currentApp = 2;
  startOpen = false;

  tft.fillScreen(blue);

  tft.setTextColor(white);
  tft.setTextSize(2);
  tft.setCursor(12, 12);
  tft.print("Settings");

  tft.setTextSize(1);
  tft.setCursor(12, 65);
  tft.print("Cyd OS Version: 1.0");

  tft.setCursor(12, 90);
  tft.print("Display: ILI9341");

  tft.setCursor(12, 115);
  tft.print("Touch: XPT2046");

  tft.setCursor(12, 140);
  tft.print("RAM: 512 KB");

  tft.setCursor(12, 165);
  tft.print("Storage: SD card");

  tft.fillRect(0, 214, SW, 26, dark);
  tft.setCursor(10, 224);
  tft.print("Tap START to return");
}

void handleTouch() {
  if (!touch.touched()) return;

  TS_Point p = touch.getPoint();

  // Initial touch calibration.
  // These values may need adjustment.
  int x = map(p.y, 200, 3900, 0, SW);
  int y = map(p.x, 200, 3900, SH, 0);

  x = constrain(x, 0, SW - 1);
  y = constrain(y, 0, SH - 1);

  if (y > 214) {
    if (currentApp != 0) {
      desktop();
    } else {
      startMenu();
    }
    delay(250);
    return;
  }

  if (startOpen) {
    if (y > 120 && y < 150) calculator();
    else if (y >= 150 && y < 175) settings();
    else if (y >= 175) desktop();

    delay(250);
    return;
  }

  if (currentApp == 0) {
    if (x < 75 && y > 40 && y < 110) {
      settings();
    } else if (x > 75 && x < 150 && y > 40 && y < 110) {
      calculator();
    } else if (x > 150 && x < 225 && y > 40 && y < 110) {
      settings();
    }
  }

  delay(250);
}

void setup() {
  Serial.begin(115200);

  // Display SPI
  SPI.begin(14, 12, 13, TFT_CS);

  // Touch SPI
  touchSPI.begin(25, 39, 32, TOUCH_CS);
  touch.begin(touchSPI);
  touch.setRotation(1);

  // Display
  tft.begin();
  tft.setRotation(1);
  tft.fillScreen(ILI9341_BLACK);

  desktop();
}

void loop() {
  handleTouch();
}
